import React, {useEffect, useState, useCallback} from 'react';
import axios from 'axios';
import './App.css';
import Header from './Header';
import Body from './Body';
function App() { 

  const [city, setCity] = useState('Oslo')
  const[weatherData, setWeatherData] = useState(null)

  const fetchData = useCallback(async () => {
  try{
    const response = await axios.get(`https://api.openweathermap.org/data/2.5/weather?q=${city}&units=metric&appid=a8eb5aa64568880f32d4b8f8d32e1a9d`);
    setWeatherData(response.data);
  }

  catch(error){
    setWeatherData(null);
    console.error(error);
  }

}, [city]);


useEffect(() =>{
  fetchData();
}, [fetchData]);


const handleInputChange = (e) =>{
setCity(e.target.value);
}





return(
  <div id="main">

    <form id="searchBar">
      <input type="text" placeholder="Enter City Name" value={city} onChange={handleInputChange}/>
    </form>

    {weatherData ? (
      <>
       <Header CityName={city} Temperature={weatherData.main.temp} HighTemp={weatherData.main.temp_max} LowTemp={weatherData.main.temp_min} Description={weatherData.weather[0].description}/>
       <Body Latitude={weatherData.coord.lat} Longitude={weatherData.coord.lon} WindSpeed={weatherData.wind.speed} CloudCover={weatherData.clouds.all} City={city} />
      </>
    ) :
    (
      <></>
    )
    }

  </div>
);
};
export default App;
